from pathlib import Path

from cyclopts import App

app = App(name="fileman")


@app.command
def upload(path: Path):
    print(f"Would upload: {path}")


@app.command
def download(url: str, *, dest: Path):
    print(f"Would download {url} to {dest}")


if __name__ == "__main__":
    app()
